"use strict";
const path = require("path");

const VERSION = "1.2.3";
const LIMIT = 42;

class Shape {
  constructor(sides) {
    this.sides = sides;
  }
  describe() {
    return `shape with ${this.sides} sides`;
  }
}

function format(value, width) {
  return String(value).padStart(width || 0, ".");
}

function getFormat() {
  return format;
}

const helpers = {
  twice(n) {
    return n * 2;
  },
  sep: path.sep,
};

const arrow = () => 1;

let calls = 0;
function counted() {
  calls += 1;
  return calls;
}

module.exports = { VERSION, LIMIT, Shape, format, getFormat, helpers, counted, arrow };
